import math

def gcd(a, b):
    return math.gcd(a, b)

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

good_products = []

# Iterate through all unique triples {a, b, c} such that 1 <= a < b < c <= 15
for a in range(1, 16):
    for b in range(a + 1, 16):
        for c in range(b + 1, 16):
            # Condition 1: gcd(a, b, c) = 1
            if gcd3(a, b, c) != 1:
                continue

            # Condition 2: c | ab
            if (a * b) % c != 0:
                continue

            # Condition 3: b | ac
            if (a * c) % b != 0:
                continue

            # Condition 4: a | bc
            if (b * c) % a != 0:
                continue

            # If all conditions are met, it's a good set. Calculate the product.
            product = a * b * c
            good_products.append(product)

# Sort the products and print them
good_products.sort()

# Print the results for recording in notes
print("Found good set products:")
for i, p in enumerate(good_products):
    print(f"{i+1}: {p}")

print(f"Total good sets found: {len(good_products)}")

