    # Condition 1: GCD of any three is 1. (Trivial for size 3)
    if gcd3(u1, u2, u3) != 1:
        return False

    # Condition 2: For any two, the third must divide their product.
    # Pair {u1, u2}: check u3
    if u3 != 0 and (u1 * u2) % u3 != 0:
        return False

    # Pair {u1, u3}: check u2
