import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set_3(U):
    # U = {u1, u2, u3}
    u1, u2, u3 = U[0], U[1], U[2]

    # Condition 1: GCD of any three is 1.
    if gcd3(u1, u2, u3) != 1:
        return False

    # Condition 2: For any two, the third must divide their product.
    # Pair {u1, u2}: check u3
    if u3 == 0 or (u1 * u2) % u3 != 0:
        return False

    # Pair {u1, u3}: check u2
    if u2 == 0 or (u1 * u3) % u2 != 0:
        return False

    # Pair {u2, u3}: check u1
    if u1 == 0 or (u2 * u3) % u1 != 0:
        return False

    return True

def is_perfect_square(n):
    if n < 0:
        return False
    # Using integer square root for efficiency and accuracy
    sqrt_n = math.isqrt(n)
    return sqrt_n * sqrt_n == n

# Search for |U|=3, max element <= 50
candidates_m = set()
max_element = 50

# Iterate over distinct positive integers u1 < u2 < u3
# We start from 2 since the problem specifies U is a set of positive integers,
# and u_i > 1 tends to yield more interesting results, but let's check if 1 is necessary later.
# Note: The original note showed U={1, 2, 3} fails condition 2. If u1=1, the condition
# u1 | u2 u3 is always met. We rely on u3 | u1 u2, which is u3 | u2. Since u2 < u3, this implies u3 <= u2, a contradiction unless u3=0 (impossible).
# So, for |U|=3, no element can be 1 unless the other two are equal, which is forbidden.
# Hence, we search from u1=2.
for u1 in range(2, max_element + 1):
    for u2 in range(u1 + 1, max_element + 1):
        for u3 in range(u2 + 1, max_element + 1):
            U = (u1, u2, u3)
            if is_good_set_3(U):
                m = u1 * u2 * u3
                # Exclude if m is a perfect square
                if not is_perfect_square(m):
                    candidates_m.add(m)

print(sorted(list(candidates_m)))
